import * as Keychain from 'react-native-keychain';

export async function saveCredentials(email: string, password: string): Promise<void> {
  await Keychain.setGenericPassword(email, password, {
    service: 'com.example.app.session',
    accessible: Keychain.ACCESSIBLE.WHEN_UNLOCKED_THIS_DEVICE_ONLY,
  });
}

export async function clearCredentials(): Promise<void> {
  await Keychain.resetGenericPassword();
}

import { useState, useCallback } from 'react';
import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { saveCredentials } from '../services/credentials';

interface FormErrors {
  name?: string;
  email?: string;
  password?: string;
}

function validate(name: string, email: string, password: string): FormErrors {
  const errors: FormErrors = {};
  if (name.trim().length === 0) errors.name = 'Name is required';
  if (!/\S+@\S+\.\S+/.test(email)) errors.email = 'Enter a valid email';
  if (password.length < 8) errors.password = 'Use at least 8 characters';
  return errors;
}

export function SignUpScreen(): JSX.Element {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [errors, setErrors] = useState<FormErrors>({});
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);

  const handleSubmit = useCallback(async () => {
    const nextErrors = validate(name, email, password);
    setErrors(nextErrors);
    if (Object.keys(nextErrors).length > 0) return;
    setSaving(true);
    try {
      await saveCredentials(email, password);
      setSaved(true);
    } catch (err) {
      setErrors({ password: err instanceof Error ? err.message : 'Could not save' });
    } finally {
      setSaving(false);
    }
  }, [name, email, password]);

  return (
    <SafeAreaView style={styles.safe}>
      <KeyboardAvoidingView
        style={styles.container}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <TextInput
          style={styles.input}
          value={name}
          onChangeText={setName}
          placeholder="Full name"
          accessibilityLabel="Full name"
        />
        {errors.name !== undefined && <Text style={styles.error}>{errors.name}</Text>}
        <TextInput
          style={styles.input}
          value={email}
          onChangeText={setEmail}
          placeholder="Email"
          keyboardType="email-address"
          autoCapitalize="none"
          accessibilityLabel="Email"
        />
        {errors.email !== undefined && <Text style={styles.error}>{errors.email}</Text>}
        <TextInput
          style={styles.input}
          value={password}
          onChangeText={setPassword}
          placeholder="Password"
          secureTextEntry
          accessibilityLabel="Password"
        />
        {errors.password !== undefined && <Text style={styles.error}>{errors.password}</Text>}
        <TouchableOpacity
          style={styles.button}
          onPress={handleSubmit}
          disabled={saving}
          accessibilityLabel="Create account"
        >
          <Text style={styles.buttonText}>{saving ? 'Saving…' : 'Create account'}</Text>
        </TouchableOpacity>
        {saved && <Text style={styles.success}>Account created securely.</Text>}
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1 },
  container: { flex: 1, justifyContent: 'center', padding: 24, gap: 12 },
  input: { borderWidth: 1, borderColor: '#C7C7CC', borderRadius: 8, padding: 12 },
  error: { color: '#FF3B30', fontSize: 13 },
  success: { color: '#34C759', marginTop: 8 },
  button: { backgroundColor: '#007AFF', padding: 14, borderRadius: 8, alignItems: 'center' },
  buttonText: { color: '#fff', fontWeight: '600' },
});
